/*
 * Д-34. Договор займа между физическими лицами.
 * Основа: п. 1 ст. 807 ГК (заём, где займодавец — гражданин, заключён с момента передачи денег), п. 1 ст. 808
 * (письменная форма при сумме больше 10 000 ₽), п. 1 ст. 809 (проценты; без условия о размере — ключевая ставка ЦБ),
 * п. 3 ст. 809 (проценты ежемесячно до дня возврата включительно, если не договорились иначе), п. 4 ст. 809
 * (предполагается беспроцентным между гражданами до 100 000 ₽), п. 5 ст. 809 (ростовщические проценты), п. 6 ст. 809
 * (при досрочном возврате — проценты по день возврата), п. 1–3 ст. 810 (срок; 30 дней по требованию; досрочный
 * возврат; момент возврата), ст. 811 (ст. 395 за просрочку; досрочное взыскание остатка при просрочке части).
 * Статус: ЧЕРНОВИК, не проверен юристом.
 */
(function (global) {
  "use strict";
  const { U } = global.Engine;
  const C = global.Common;
  const F = U.F;

  const person = (prefix, who) => [
    { id: prefix + "_name", type: "text", label: `ФИО ${who} полностью` },
    { id: prefix + "_birth", type: "date", label: "Дата рождения" },
    { id: prefix + "_passport", type: "text", label: "Паспорт: серия, номер, кем и когда выдан",
      hint: "Нужно, чтобы стороны были точно определены. Данные остаются в вашем браузере",
      placeholder: "45 12 345678, выдан ГУ МВД России по г. Москве 01.02.2020" },
    { id: prefix + "_address", type: "text", label: "Адрес регистрации" },
    { id: prefix + "_phone", type: "tel", label: "Телефон" },
  ];

  // равные части, остаток копеек — в последний платёж
  function schedule(amount, n, first) {
    if (!(amount > 0) || !(n >= 2) || !first) return [];
    const part = Math.floor(amount / n * 100) / 100;
    const rows = [];
    for (let i = 0; i < n; i++) {
      const sum = i < n - 1 ? part : Math.round((amount - part * (n - 1)) * 100) / 100;
      rows.push({ date: U.addMonths(first, i), sum });
    }
    return rows;
  }

  function derive(a) {
    const amount = typeof a.amount === "number" && a.amount > 0 ? a.amount : null;
    const signed = U.date(a.doc_date);
    const due = U.date(a.due_date);
    const first = U.date(a.first_date);
    const n = typeof a.parts === "number" ? Math.round(a.parts) : null;
    const plan = a.return === "parts" ? schedule(amount, n, first) : [];
    const rate = typeof a.rate === "number" ? a.rate : null;
    const keyNow = C.keyRate(U.today());
    return { amount, signed, due, first, n, plan, rate, keyNow, last: plan.length ? plan[plan.length - 1].date : due };
  }

  const pct = x => String(x).replace(".", ",");

  const spec = {
    id: "d34",
    code: "Д-34",
    title: "Договор займа между физлицами",
    lead: "Договор займа денег между людьми: сумма, срок или график возврата, проценты и ответственность за просрочку. Займёт около 10 минут.",
    status: "draft",
    disclaimer: "Договор составлен по вашим ответам и не является юридической консультацией. Перед подписанием прочитайте его целиком обеим сторонам.",

    steps: [
      {
        id: "money", title: "Сумма и передача",
        questions: [
          { id: "role", type: "choice", label: "Кто заполняет?", hint: "На текст договора не влияет, только на подсказки", options: [
            { value: "lender", label: "Даю деньги в долг" },
            { value: "borrower", label: "Беру деньги в долг" },
          ] },
          { id: "city", type: "text", label: "Город, где подписываете договор", placeholder: "г. Москва" },
          { id: "doc_date", type: "date", future: true, label: "Дата договора" },
          { id: "amount", type: "money", label: "Сумма займа", suffix: "₽", min: 1, hint: "Только рубли. В договоре будет цифрами и прописью" },
          { id: "how", type: "choice", label: "Как передаются деньги?", options: [
            { value: "cash", label: "Наличными при подписании договора" },
            { value: "transfer", label: "Переводом на счёт заёмщика" },
          ] },
          { id: "transfer_days", type: "number", label: "В течение скольких дней после подписания перевести?", min: 1, show: a => a.how === "transfer",
            validate: v => v > 30 ? "Не больше 30 дней" : null },
        ],
      },
      {
        id: "return", title: "Возврат",
        questions: [
          { id: "return", type: "choice", label: "Как возвращать?", options: [
            { value: "date", label: "Всю сумму до определённой даты" },
            { value: "parts", label: "Частями, каждый месяц" },
            { value: "demand", label: "По требованию займодавца", hint: "Тогда долг возвращается в течение 30 дней после требования" },
          ] },
          { id: "due_date", type: "date", future: true, label: "Вернуть не позднее", show: a => a.return === "date",
            validate: (v, a) => { const s = U.date(a.doc_date), x = U.date(v); return s && x && x <= s ? "Позже даты договора" : null; } },
          { id: "parts", type: "number", label: "Сколько платежей?", min: 2, show: a => a.return === "parts",
            validate: v => v > 60 ? "Не больше 60 платежей" : Math.round(v) !== v ? "Целое число" : null },
          { id: "first_date", type: "date", future: true, label: "Дата первого платежа", hint: "Дальше — в то же число каждого месяца", show: a => a.return === "parts",
            validate: (v, a) => { const s = U.date(a.doc_date), x = U.date(v); return s && x && x <= s ? "Позже даты договора" : null; } },
          { id: "back_how", type: "choice", label: "Как заёмщик возвращает деньги?", options: [
            { value: "account", label: "Переводом на счёт займодавца" },
            { value: "any", label: "Переводом или наличными под расписку" },
          ] },
        ],
      },
      {
        id: "interest", title: "Проценты",
        questions: [
          { id: "interest", type: "choice", label: "Проценты за пользование деньгами?",
            hint: "Если без процентов, в договоре будет прямо написано, что заём беспроцентный. Без этой фразы при сумме больше 100 000 ₽ проценты начислялись бы по ключевой ставке ЦБ", options: [
            { value: "none", label: "Без процентов" },
            { value: "rate", label: "С процентами" },
          ] },
          { id: "rate", type: "number", label: "Сколько процентов годовых?", suffix: "% годовых", min: 0.01, show: a => a.interest === "rate" },
          { id: "rate_pay", type: "choice", label: "Когда платить проценты?", show: a => a.interest === "rate", options: [
            { value: "monthly", label: "Каждый месяц", hint: "Так по закону, если не договорились иначе" },
            { value: "end", label: "Вместе с возвратом долга" },
          ] },
          { id: "rate_day", type: "number", label: "До какого числа месяца платить проценты?", min: 1, show: a => a.rate_pay === "monthly",
            validate: v => v > 28 ? "Не позже 28-го, чтобы число было в каждом месяце" : null },
          { id: "penalty", type: "choice", label: "Если заёмщик не вернёт вовремя?", options: [
            { value: "law", label: "Проценты по закону", hint: "По ключевой ставке ЦБ за каждый день просрочки (ст. 395 ГК)" },
            { value: "custom", label: "Своя неустойка — процент в день" },
          ] },
          { id: "penalty_rate", type: "number", label: "Неустойка, % в день от просроченной суммы", suffix: "% в день", min: 0.01, show: a => a.penalty === "custom",
            hint: "Часто ставят 0,1% в день. Слишком большую неустойку суд может уменьшить (ст. 333 ГК)" },
        ],
      },
      {
        id: "parties", title: "Стороны",
        questions: [
          ...person("lender", "займодавца (кто даёт деньги)"),
          ...person("borrower", "заёмщика (кто берёт деньги)"),
        ],
      },
    ],

    derive,

    render(a, d) {
      const P = [];
      const H = t => P.push({ text: t, align: "center", bold: true, before: 180, after: 60, keepNext: true });
      const T = t => P.push({ text: t, indent: true });
      const who = (prefix, role) => `${F(a[prefix + "_name"], "ФИО")}, ${F(U.fmtDate(U.date(a[prefix + "_birth"])), "дата рождения")} г. р., паспорт ${F(a[prefix + "_passport"], "паспорт")}, зарегистрированный(ая) по адресу: ${F(a[prefix + "_address"], "адрес")}, именуемый(ая) в дальнейшем «${role}»`;
      const money = d.amount ? C.rubles(d.amount) : F(null, "сумма");
      const withRate = a.interest === "rate";

      P.push({ text: "ДОГОВОР ЗАЙМА", align: "center", bold: true, after: 120 });
      P.push({ text: `${F(a.city, "город")}                                                                          ${F(U.fmtDateLong(d.signed), "дата")}`, align: "left", after: 240 });
      T(`${who("lender", "Займодавец")}, с одной стороны, и ${who("borrower", "Заёмщик")}, с другой стороны, заключили настоящий договор о нижеследующем.`);

      H("1. Предмет договора");
      T(`1.1. Займодавец передаёт в собственность Заёмщику денежные средства в размере ${money} (далее — сумма займа), а Заёмщик обязуется возвратить Займодавцу такую же сумму` + (withRate ? " и уплатить проценты за пользование займом" : "") + " в порядке и сроки, предусмотренные договором.");
      if (withRate) T(`1.2. За пользование займом Заёмщик уплачивает проценты в размере ${F(d.rate != null ? pct(d.rate) : null, "ставка")}% годовых.`);
      else if (a.interest === "none") T("1.2. Заём является беспроцентным: проценты за пользование займом не начисляются и не уплачиваются.");
      else T(F(null, "проценты"));

      H("2. Передача суммы займа");
      if (a.how === "transfer") T(`2.1. Займодавец перечисляет сумму займа на банковский счёт Заёмщика в течение ${F(a.transfer_days, "число")} дней со дня подписания договора по реквизитам: ____________________________________________. Сумма займа считается переданной в день её зачисления на счёт Заёмщика.`);
      else if (a.how === "cash") T("2.1. Займодавец передаёт Заёмщику сумму займа наличными в момент подписания договора. Получение суммы займа Заёмщик подтверждает собственноручной записью в разделе 7 договора и распиской.");
      else T(F(null, "как передаются деньги"));
      T("2.2. Договор считается заключённым с момента передачи суммы займа Заёмщику (п. 1 ст. 807 ГК РФ).");

      H("3. Возврат суммы займа");
      if (a.return === "date") T(`3.1. Заёмщик возвращает сумму займа в полном объёме не позднее ${F(U.fmtDate(d.due), "дата")} включительно.`);
      else if (a.return === "demand") T("3.1. Заёмщик возвращает сумму займа в течение тридцати дней со дня предъявления Займодавцем письменного требования о возврате (п. 1 ст. 810 ГК РФ).");
      else if (a.return === "parts") {
        T(`3.1. Заёмщик возвращает сумму займа частями в соответствии с графиком:`);
        if (d.plan.length) P.push({ text: d.plan.map((r, i) => `${i + 1}) не позднее ${U.fmtDate(r.date)} — ${U.money(r.sum)} руб.`).join("\n"), align: "left", leftIndent: 709 });
        else P.push({ text: F(null, "график платежей"), indent: true });
      } else T(F(null, "срок возврата"));
      T("3.2. Возврат производится " + (a.back_how === "any" ? "переводом на банковский счёт Займодавца либо наличными денежными средствами с выдачей Займодавцем расписки в получении." : "переводом на банковский счёт Займодавца по реквизитам, которые Займодавец сообщает Заёмщику в письменной форме или в сообщении с телефона, указанного в договоре.") + " Сумма займа считается возвращённой в момент её передачи Займодавцу или зачисления на банковский счёт Займодавца (п. 3 ст. 810 ГК РФ).");
      if (withRate) T("3.3. Заёмщик вправе возвратить сумму займа досрочно полностью или по частям, уведомив Займодавца в письменной форме не менее чем за тридцать дней до дня такого возврата (п. 2 ст. 810 ГК РФ). В этом случае проценты уплачиваются по день возврата суммы займа или её части включительно (п. 6 ст. 809 ГК РФ).");
      else T("3.3. Заёмщик вправе возвратить сумму займа досрочно полностью или частично (п. 2 ст. 810 ГК РФ).");
      if (withRate) {
        H("4. Проценты");
        T("4.1. Проценты начисляются на остаток суммы займа со дня, следующего за днём её передачи Заёмщику, по день возврата суммы займа включительно. При начислении процентов в расчёт принимается фактическое количество дней в году (365 или 366).");
        if (a.rate_pay === "end") T("4.2. Проценты уплачиваются одновременно с возвратом суммы займа" + (a.return === "parts" ? ", то есть с каждым платежом по графику — на возвращаемую часть за период пользования ею." : "."));
        else T(`4.2. Проценты уплачиваются ежемесячно не позднее ${F(a.rate_day, "число")}-го числа каждого месяца за предыдущий месяц, а за последний период — одновременно с возвратом суммы займа.`);
      }
      const n = withRate ? 5 : 4;
      H(`${n}. Ответственность сторон`);
      if (a.penalty === "custom") T(`${n}.1. За несвоевременный возврат суммы займа (её части) Заёмщик уплачивает Займодавцу неустойку в размере ${F(a.penalty_rate != null ? pct(a.penalty_rate) : null, "процент")}% от просроченной суммы за каждый день просрочки.`);
      else T(`${n}.1. В случае невозврата суммы займа (её части) в срок на эту сумму подлежат уплате проценты в размере, предусмотренном п. 1 ст. 395 ГК РФ, со дня, когда она должна была быть возвращена, по день её возврата Займодавцу, независимо от уплаты процентов за пользование займом (п. 1 ст. 811 ГК РФ).`);
      if (a.return === "parts") T(`${n}.2. При нарушении Заёмщиком срока возврата очередной части займа Займодавец вправе потребовать досрочного возврата всей оставшейся суммы займа вместе с причитающимися процентами (п. 2 ст. 811 ГК РФ).`);

      H(`${n + 1}. Заключительные положения`);
      T(`${n + 1}.1. Изменения и дополнения к договору действительны, если совершены в письменной форме и подписаны обеими сторонами.`);
      T(`${n + 1}.2. Требования и уведомления направляются по адресам сторон, указанным в договоре, заказным или ценным письмом либо вручаются под подпись. Сторона, сменившая адрес, сообщает об этом другой стороне в течение 5 дней.`);
      T(`${n + 1}.3. Споры разрешаются путём переговоров, а при недостижении согласия — в суде в порядке, установленном законодательством Российской Федерации.`);
      T(`${n + 1}.4. Договор составлен в двух экземплярах, имеющих равную силу, по одному для каждой стороны.`);

      H(`${n + 2}. Подписи сторон`);
      P.push({ text: `Займодавец: ${F(a.lender_name, "ФИО")}\nТел.: ${F(a.lender_phone, "телефон")}\n\n____________ / ${F(U.shortName(a.lender_name), "И. О. Фамилия")}`, align: "left", after: 240 });
      P.push({ text: `Заёмщик: ${F(a.borrower_name, "ФИО")}\nТел.: ${F(a.borrower_phone, "телефон")}\n\n____________ / ${F(U.shortName(a.borrower_name), "И. О. Фамилия")}`, align: "left", after: 240 });
      if (a.how === "cash") P.push({ text: `Сумму займа ${money} наличными получил(а) полностью:\n\n____________________ (подпись)\n\n__________________________________________________\n(ФИО заёмщика полностью, собственноручно)`, align: "left", before: 240 });
      return P;
    },

    guidance(a, d) {
      const g = [
        { title: "Подпишите два экземпляра — по одному каждой стороне.", text: "Проверьте паспорта друг друга: ФИО и данные должны совпадать с договором." },
      ];
      if (a.how === "cash") g.push({ title: "При передаче наличных возьмите ещё и расписку (Д-33).", text: "Договор займа между людьми вступает в силу только с передачей денег. Запись о получении в договоре плюс отдельная расписка — надёжное доказательство, что деньги переданы." });
      if (a.how === "transfer") g.push({ title: "Переводите с назначением платежа.", text: "Например: «Перечисление суммы займа по договору от такой-то даты». Выписка из банка — доказательство передачи денег." });
      if (a.return === "demand") g.push({ title: "Чтобы вернуть деньги, нужно письменное требование (Д-35).", text: "Долг становится просроченным через 30 дней после того, как заёмщик получил требование." });
      if (a.interest === "rate" && d.rate != null && d.keyNow && d.rate > d.keyNow * 2) g.push({ title: "Высокие проценты суд может снизить.", text: `Если ставка в два и более раза выше обычной для таких займов, суд может уменьшить её (п. 5 ст. 809 ГК). Сейчас ключевая ставка ЦБ — ${pct(d.keyNow)}%.` });
      if (a.role === "lender" && a.interest === "rate") g.push({ title: "Проценты по займу — ваш доход.", text: "С полученных процентов нужно заплатить НДФЛ и подать декларацию 3-НДФЛ." });
      g.push({ title: "Каждый платёж — с подтверждением.", text: "Переводы с назначением «возврат займа по договору от…» или расписки займодавца о получении (Д-33)." });
      return g;
    },

    fileName(a) { return "Договор займа" + (a.borrower_name ? " — " + U.shortName(a.borrower_name) : ""); },
  };

  global.DOCS = global.DOCS || {};
  global.DOCS.d34 = spec;
})(typeof window !== "undefined" ? window : globalThis);
